// Общий код для проверок готовых отчётов (#83178a, #4b397a): кандидат по имени (list_candidates, как экран /candidates)
// → /candidates/<id>/report, ожидание итога. Только чтение.
import { Page, Locator } from '@playwright/test';
import { expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { listCandidates } from '../candidates/hiring-support';

/** Открыть отчёт кандидата с именем name (точное совпадение) или первым подходящим под RegExp. */
export async function openReport(page: Page, name: string | RegExp): Promise<{ id: string; name: string }> {
  const api = await openWithApi(page, '/candidates');
  const all = await listCandidates(api);
  const found = all.filter((c) => (typeof name === 'string' ? c.full_name === name : name.test(c.full_name)));
  expect(found.length, `кандидат «${name}» не найден в list_candidates (QA-данные 21.10.2026)`).toBeGreaterThan(0);
  if (typeof name === 'string') expect(found, `кандидат «${name}» не уникален`).toHaveLength(1);
  const c = found[0];
  await page.goto(`/candidates/${c.id}/report`);
  await expect(page.getByTestId('report-summary'), `у «${c.full_name}» нет готового отчёта`).toBeVisible({ timeout: 30_000 });
  return { id: c.id, name: c.full_name };
}

/** Итог, объяснения всех доменов и всех точек отчёта. */
export const explanations = (page: Page) => ({
  summary: page.getByTestId('report-summary'),
  domains: page.getByTestId('domain-explanation'),
  checkpoints: page.getByTestId('checkpoint-explanation'),
});

/** Тексты всех элементов локатора. */
export const texts = (l: Locator) => l.allInnerTexts();
